// === Tab: mySketch ===
let bgcolor = '#620384';
let fcolor = '#f14190';

let count = 0;
let cor = fcolor;

function drawitself(arr) {

	arr.p1x = (arr.rx) + (Math.cos(arr.a)*arr.r);
	arr.p1y = (arr.ry) + (Math.sin(arr.a)*arr.r);
	arr.p2x = (arr.rx) + (Math.cos(arr.a)*(arr.r + arr.esp));
	arr.p2y = (arr.ry) + (Math.sin(arr.a)*(arr.r + arr.esp));

	line(arr.p1x, arr.p1y, arr.p2x, arr.p2y);

	if (Math.random()*100 > 98) {

		arr.newr = int(Math.random()*150);

		arr.deltax = Math.cos(arr.a)*(arr.r) + Math.cos(arr.a)*(arr.newr+arr.esp);
		arr.deltay = Math.sin(arr.a)*(arr.r) + Math.sin(arr.a)*(arr.newr+arr.esp);

		arr.r = arr.newr;
		arr.rx = arr.rx + arr.deltax;
		arr.ry = arr.ry + arr.deltay;

		arr.a = arr.a - Math.PI;
		arr.dir = arr.dir * -1;
		arr.step = Math.random()*0.06;
	}

	arr.a = arr.a + (arr.dir * arr.step);

}


let xpto = {};
let trilhas = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(bgcolor);

	for (let k=0; k<16; k++) {

		trilhas[k] = {
				detax: 0,
				deltay: 0,
				newr: 0,
				a: Math.random()*(2*Math.PI),
				r: (80 + Math.random()*(180)),
				esp: Math.random()*(150),
				step: Math.random()*(0.1),
				rx: 100,
				ry: 100,
				dir: 1,
				p1x: 0,
				p1y: 0,
				p2x: 0,
				p2y: 0
		 }

		 trilhas[k].rx = Math.random()*windowWidth;
		 trilhas[k].ry = Math.random()*windowHeight;

	}




}



function draw() {



	  count++;
	  if (count > 2000) {

			if (cor == fcolor) {
				cor = bgcolor;
			} else {
				cor = fcolor;
			}

			count = 0;

		}


		for (let z=0; z<16; z++) {
		  stroke(cor);
			drawitself(trilhas[z]);

		}


}

